// Eingehende Buchungsanfrage normalisieren
// Quellen: Web-Widget, WhatsApp, Vapi Voicebot
const body = $input.first().json.body || $input.first().json;

const request = {
  salon_id: body.salon_id || 'a0000000-0000-0000-0000-000000000001',
  client_name: body.client_name || body.name || '',
  client_phone: body.client_phone || body.phone || '',
  client_email: body.client_email || body.email || '',
  service_name: body.service_name || body.service || '',
  service_id: body.service_id || null,
  staff_name: body.staff_name || body.staff || '',
  staff_id: body.staff_id || null,
  preferred_date: body.preferred_date || body.date || '',
  preferred_time: body.preferred_time || body.time || '',
  source: body.source || 'web',
  notes: body.notes || ''
};

// Validierung
const errors = [];
if (!request.client_name) errors.push('client_name fehlt');
if (!request.client_phone) errors.push('client_phone fehlt');
if (!request.service_name && !request.service_id) errors.push('service fehlt');
if (!request.preferred_date) errors.push('preferred_date fehlt');

if (errors.length > 0) {
  return [{ json: { valid: false, errors } }];
}

return [{ json: { valid: true, ...request } }];

// Bestätigungsnachricht zusammenbauen
const booking = $('DB: Termin buchen').item.json;
const service = $('DB: Service suchen').item.json;
const staff = $('DB: Verfügbare Stylisten').item.json;
const client = $('Validiere Anfrage').item.json;

const startDate = new Date(booking.start_time);
const dateStr = startDate.toLocaleDateString('de-DE', { weekday: 'long', day: 'numeric', month: 'long' });
const timeStr = startDate.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
const price = (service.price_cents / 100).toFixed(2).replace('.', ',');

const message = `✅ Termin bestätigt!

📅 ${dateStr} um ${timeStr} Uhr
💇 ${service.name}
👤 bei ${staff.staff_name}
💰 ${price} €

Wir freuen uns auf dich! 😊
Zum Umbuchen oder Stornieren einfach hier antworten.`;

return [{
  json: {
    booking_id: booking.booking_id,
    client_phone: client.client_phone,
    client_name: client.client_name,
    message,
    source: client.source
  }
}];
